// F1 regression: localhost only, in-memory credentials, no product writes or recordings.
import { createRequire } from 'node:module'

const require = createRequire(new URL('../package.json', import.meta.url))
const { chromium, expect } = require('@playwright/test')
const axeModule = require('@axe-core/playwright')
const AxeBuilder = axeModule.default ?? axeModule.AxeBuilder ?? axeModule
const ORIGIN = 'http://localhost:5173'
const checks = []
const scans = []
let browser
let context
let page
let rateLimited = false
let blockedExternalRequests = 0
let blockedWrites = 0
let productWriteRequests = 0
let baselineCount = null
let finalCount = null
let failure = null
let currentStep = 'setup'
let failedStep = null
let failureCategory = null

function step(id) {
  currentStep = id
  console.log(JSON.stringify({ step: id }))
}

function result(id, passed) {
  checks.push({ id, passed: Boolean(passed) })
  console.log(JSON.stringify({ check: id, passed: Boolean(passed) }))
}

function requireCondition(condition, reason) {
  if (!condition) throw new Error(reason)
}

async function focused(locator) {
  return locator.evaluate(element => element === document.activeElement)
}

async function assertFocus(locator, checkId) {
  try {
    // Observe focus with retrying assertions; never move it to satisfy a check.
    await expect(locator).toBeFocused({ timeout: 7000 })
    result(checkId, true)
  } catch (error) {
    result(checkId, false)
    throw error
  }
}

async function focusByTab(locator, backwards = false) {
  for (let index = 0; index < 100; index++) {
    if (await focused(locator)) return true
    await page.keyboard.press(backwards ? 'Shift+Tab' : 'Tab')
  }
  return false
}

async function scan(screen) {
  step(`axe-${screen}`)
  await page.evaluate(async () => { await document.fonts.ready })
  const analyzed = await new AxeBuilder({ page }).analyze()
  // Never serialize raw HTML, accessibility trees, inputs, cookies or request logs.
  const summary = {
    screen,
    violations: analyzed.violations.map(rule => ({
      id: rule.id,
      impact: rule.impact,
      affectedNodes: rule.nodes.length,
      targets: rule.nodes.map(node => node.target),
    })),
    incomplete: analyzed.incomplete.map(rule => ({ id: rule.id, affectedNodes: rule.nodes.length })),
    passedRules: analyzed.passes.length,
  }
  scans.push(summary)
  console.log(JSON.stringify({ axe: summary }))
}

async function countProducts() {
  return page.evaluate(async () => {
    const response = await fetch('/api/v1/products?page=0&size=1', {
      credentials: 'include', signal: AbortSignal.timeout(10_000),
    })
    if (response.status !== 200) return { status: response.status, count: null }
    const body = await response.json()
    return { status: response.status, count: body.totalElements }
  })
}

async function main() {
  step('browser-setup')
  const password = process.env.DEV_ADMIN_PASSWORD
  requireCondition(password, 'QA_MISSING_CREDENTIALS')
  browser = await chromium.launch({ headless: true, timeout: 15_000 })
  context = await browser.newContext({
    baseURL: ORIGIN, viewport: { width: 1440, height: 1000 },
    serviceWorkers: 'block', reducedMotion: 'reduce',
    // No tracing, screenshots, video, HAR or storage-state serialization.
  })
  await context.route('**/*', route => {
    const request = route.request()
    const url = new URL(request.url())
    if (url.origin !== ORIGIN) {
      blockedExternalRequests++
      return route.abort('blockedbyclient')
    }
    if (!['GET', 'HEAD', 'OPTIONS'].includes(request.method())
        && !(request.method() === 'POST'
          && ['/api/v1/auth/login', '/api/v1/auth/logout'].includes(url.pathname))) {
      blockedWrites++
      return route.abort('blockedbyclient')
    }
    return route.continue()
  })
  await context.routeWebSocket('**/*', socket => {
    if (new URL(socket.url()).origin === 'ws://localhost:5173') socket.connectToServer()
    else { blockedExternalRequests++; socket.close() }
  })
  context.on('response', response => {
    if (response.status() === 429) rateLimited = true
  })
  page = await context.newPage()
  page.setDefaultTimeout(7000)
  page.setDefaultNavigationTimeout(15000)
  page.on('request', request => {
    if (new URL(request.url()).pathname.startsWith('/api/v1/products')
        && !['GET', 'HEAD', 'OPTIONS'].includes(request.method())) productWriteRequests++
  })

  step('login-navigation')
  await page.goto('/login')
  const username = page.getByLabel(/^Username(?:\s*\*)?\s*$/)
  const passwordInput = page.getByLabel(/^Password(?:\s*\*)?\s*$/)
  const signIn = page.getByRole('button', { name: 'Sign in', exact: true })
  await username.waitFor({ state: 'visible' })
  result('login-username-autofocus', await focused(username))
  await scan('login')
  // The login scan happens before any credential is entered.
  step('login-keyboard-submit')
  requireCondition(await focused(username), 'QA_LOGIN_FOCUS_FAILED')
  await page.keyboard.insertText(process.env.DEV_ADMIN_USERNAME || 'admin')
  await page.keyboard.press('Tab')
  result('login-tab-to-password', await focused(passwordInput))
  requireCondition(await focused(passwordInput), 'QA_LOGIN_FOCUS_FAILED')
  await page.keyboard.insertText(password)
  await page.keyboard.press('Tab')
  result('login-tab-to-submit', await focused(signIn))
  requireCondition(await focused(signIn), 'QA_LOGIN_FOCUS_FAILED')
  const loggedIn = page.waitForResponse(response => new URL(response.url()).pathname === '/api/v1/auth/login'
    && response.request().method() === 'POST')
  await page.keyboard.press('Enter')
  const loginStatus = (await loggedIn).status()
  requireCondition(loginStatus !== 429, 'QA_RATE_LIMITED')
  requireCondition(loginStatus === 200, 'QA_AUTH_FAILED')
  await page.waitForURL(`${ORIGIN}/dashboard`)
  result('login-keyboard-submit', true)
  const initial = await countProducts()
  baselineCount = initial.count
  requireCondition(initial.status === 200 && baselineCount === 500, 'QA_BASELINE_MISMATCH')

  const overview = page.getByRole('link', { name: 'Overview', exact: true })
  const products = page.getByRole('link', { name: 'Products', exact: true })
  const topAdd = page.locator('button.top-create')
  const account = page.getByRole('button', { name: /^Account menu for / })
  const home = page.getByRole('link', { name: 'FFieldnote. home', exact: true })
  await page.getByRole('img', { name: 'Bar chart showing product counts by category', exact: true }).waitFor()
  await scan('dashboard')
  step('header-keyboard-navigation')
  await home.focus()
  for (const [label, locator] of [['overview', overview], ['products', products], ['create', topAdd], ['account', account]]) {
    await page.keyboard.press('Tab')
    result(`header-tab-${label}`, await focused(locator))
  }
  requireCondition(await focused(account), 'QA_HEADER_FOCUS_FAILED')
  await page.keyboard.press('Enter')
  await page.getByRole('menu').waitFor()
  await page.keyboard.press('Escape')
  await page.getByRole('menu').waitFor({ state: 'hidden' })
  result('account-menu-escape-restores-focus', await focused(account))
  requireCondition(await focusByTab(products, true), 'QA_KEYBOARD_NAVIGATION_FAILED')
  await page.keyboard.press('Enter')
  await page.waitForURL(`${ORIGIN}/products`)
  await page.getByRole('table', { name: 'Product catalogue' }).getByRole('row').nth(1).waitFor()
  result('keyboard-navigation-to-products', true)
  await scan('products')

  step('product-filter-keyboard-navigation')
  const search = page.getByRole('textbox', { name: 'Search products', exact: true })
  const category = page.getByRole('combobox', { name: 'Category', exact: true })
  const minPrice = page.getByRole('spinbutton', { name: 'Min price', exact: true })
  const maxPrice = page.getByRole('spinbutton', { name: 'Max price', exact: true })
  result('products-search-reachable-by-tab', await focusByTab(search))
  await page.keyboard.press('Tab')
  result('products-tab-to-category', await focused(category))
  requireCondition(await focused(category), 'QA_FILTER_FOCUS_FAILED')
  await page.keyboard.press('Enter')
  await page.getByRole('listbox').waitFor()
  await page.keyboard.press('Escape')
  await page.getByRole('listbox').waitFor({ state: 'hidden' })
  result('category-escape-restores-focus', await focused(category))
  for (const [label, locator] of [['min-price', minPrice], ['max-price', maxPrice]]) {
    await page.keyboard.press('Tab')
    result(`products-tab-${label}`, await focused(locator))
  }
  const sort = page.getByRole('table', { name: 'Product catalogue' }).getByRole('button', { name: 'Product', exact: true })
  await page.keyboard.press('Tab')
  result('products-sort-reachable-by-tab', await focused(sort))

  // Complete the fourth required screen before dialog checks, without dropping
  // any assertion if the dialog phase later exposes a real focus defect.
  step('form-keyboard-navigation')
  requireCondition(await focusByTab(topAdd, true), 'QA_CREATE_LINK_UNREACHABLE')
  await page.keyboard.press('Enter')
  await page.waitForURL(`${ORIGIN}/products/new`)
  await page.getByRole('heading', { name: 'Add a product', exact: true }).waitFor()
  result('keyboard-navigation-to-form', true)
  await scan('form')
  step('form-keyboard-tab-order')
  const name = page.getByLabel(/^Product name(?:\s*\*)?\s*$/)
  result('form-name-reachable-by-tab', await focusByTab(name))
  for (const [label, locator] of [
    ['category', page.getByLabel(/^Category(?:\s*\*)?\s*$/)],
    ['price', page.getByLabel(/^Price(?:\s*\*)?\s*$/)],
    ['stock', page.getByLabel(/^Stock quantity(?:\s*\*)?\s*$/)],
    ['description', page.getByLabel('Description', { exact: true })],
    ['tags', page.getByLabel('Tags', { exact: true })],
    ['specs', page.getByLabel('Specifications (JSON)', { exact: true })],
    ['active', page.getByLabel('Product is active', { exact: true })],
    ['cancel', page.getByRole('link', { name: 'Cancel', exact: true })],
    ['submit', page.getByRole('button', { name: 'Create product', exact: true })],
  ]) {
    step(`form-tab-${label}`)
    await page.keyboard.press('Tab')
    await assertFocus(locator, `form-tab-${label}`)
  }
  step('form-keyboard-cancel')
  await page.keyboard.press('Shift+Tab')
  requireCondition(await focused(page.getByRole('link', { name: 'Cancel', exact: true })), 'QA_FORM_CANCEL_UNREACHABLE')
  await page.keyboard.press('Enter')
  await page.waitForURL(`${ORIGIN}/products`)
  result('form-keyboard-cancel', true)
  await page.getByRole('table', { name: 'Product catalogue' }).getByRole('row').nth(1).waitFor()

  step('delete-trigger-keyboard-focus')
  const remove = page.getByRole('button', { name: /^Delete / }).first()
  await expect(remove).toBeVisible()
  requireCondition(await focusByTab(remove), 'QA_DELETE_TRIGGER_UNREACHABLE')
  step('delete-dialog-keyboard-open')
  await page.keyboard.press('Enter')
  const dialog = page.getByRole('dialog', { name: 'Remove this product?', exact: true })
  const keep = dialog.getByRole('button', { name: 'Keep product', exact: true })
  const confirm = dialog.getByRole('button', { name: 'Remove product', exact: true })
  await dialog.waitFor()
  await keep.waitFor()
  step('delete-dialog-initial-focus')
  await assertFocus(keep, 'dialog-initial-focus-safe-cancel')
  await scan('delete-dialog')
  for (const [label, key, locator] of [
    ['forward-confirm', 'Tab', confirm], ['forward-wrap', 'Tab', keep],
    ['backward-wrap', 'Shift+Tab', confirm], ['backward-cancel', 'Shift+Tab', keep],
  ]) {
    step(`dialog-focus-trap-${label}`)
    await page.keyboard.press(key)
    await assertFocus(locator, `dialog-focus-trap-${label}`)
  }
  step('dialog-escape-focus-restoration')
  await page.keyboard.press('Escape')
  await dialog.waitFor({ state: 'hidden' })
  await assertFocus(remove, 'dialog-escape-restores-trigger-focus')
  requireCondition(await focused(remove), 'QA_DIALOG_FOCUS_RESTORE_FAILED')
  await page.keyboard.press('Enter')
  await dialog.waitFor()
  step('dialog-reopen-cancel-focus')
  await assertFocus(keep, 'dialog-reopen-initial-focus-safe-cancel')
  step('dialog-keyboard-cancel')
  await page.keyboard.press('Enter')
  await dialog.waitFor({ state: 'hidden' })
  await assertFocus(remove, 'dialog-keyboard-cancel-restores-focus')
}

try {
  await main()
} catch (error) {
  const message = String(error?.message || '')
  failedStep = currentStep
  failureCategory = /strict mode violation/i.test(message) ? 'locator-not-unique'
    : /Timeout|timed out/i.test(message) ? 'timeout'
      : /toBeFocused|expect\(/.test(message) ? 'assertion'
        : 'runner-error'
  // Discard raw Playwright call logs; fill actions could contain credentials.
  failure = /^QA_[A-Z_]+$/.test(message) ? message
    : /Executable doesn.t exist/.test(message) ? 'QA_BROWSER_UNAVAILABLE'
      : 'QA_RUNNER_OR_ASSERTION_FAILED'
  if (page && !page.isClosed()) {
    try {
      const state = await page.evaluate(() => ({
        activeTag: document.activeElement?.tagName ?? null,
        activeIsBody: document.activeElement === document.body,
        focusInDialog: Boolean(document.activeElement?.closest('[role="dialog"]')),
        dialogCount: document.querySelectorAll('[role="dialog"]').length,
      }))
      console.log(JSON.stringify({ failureDiagnostic: { step: failedStep, category: failureCategory, ...state } }))
    } catch { /* Do not expose raw browser errors when the context is gone. */ }
  }
} finally {
  if (page && !page.isClosed()) {
    try {
      const final = await countProducts()
      if (final.status === 200) finalCount = final.count
    } catch { /* Report only the missing count below. */ }
  }
  await context?.close().catch(() => {})
  await browser?.close().catch(() => {})
}
result('product-count-unchanged', baselineCount === 500 && finalCount === 500)
result('no-product-write-requests', productWriteRequests === 0 && blockedWrites === 0)
const summary = {
  failure: rateLimited ? 'QA_RATE_LIMITED' : failure,
  failedStep, failureCategory,
  rateLimited, baselineCount, finalCount,
  productWriteRequests, blockedWrites, blockedExternalRequests,
  scans: scans.map(item => ({ screen: item.screen, violations: item.violations.length,
    affectedNodes: item.violations.reduce((sum, rule) => sum + rule.affectedNodes, 0),
    incompleteRules: item.incomplete.length })),
  passedChecks: checks.filter(check => check.passed).length,
  failedChecks: checks.filter(check => !check.passed).map(check => check.id),
  recordingsEnabled: false,
}
console.log(JSON.stringify({ summary }))
if (summary.failure || summary.failedChecks.length || scans.length !== 5
    || scans.some(item => item.violations.length)) process.exitCode = 1

import { randomUUID } from 'node:crypto'
import type { Page } from '@playwright/test'
import { test, expect, credentialsFor } from './support/fixtures'
import { QaFailure, UI_ORIGIN } from './support/qa-api'

// E2 deliberately uses the Vite proxy only, never the backend origin directly.
test.beforeEach(async ({ context }) => {
  await context.route('**/*', route => new URL(route.request().url()).origin === UI_ORIGIN
    ? route.fallback() : route.abort('blockedbyclient'))
  await context.routeWebSocket('**/*', socket => {
    if (new URL(socket.url()).origin === 'ws://localhost:5173') socket.connectToServer()
    else socket.close()
  })
})

async function submitLogin(page: Page, username: string, password: string): Promise<number> {
  await page.getByLabel(/^Username(?:\s*\*)?\s*$/).fill(username)
  await page.getByLabel(/^Password(?:\s*\*)?\s*$/).fill(password)
  const response = page.waitForResponse(item => new URL(item.url()).pathname === '/api/v1/auth/login'
    && item.request().method() === 'POST')
  await page.getByRole('button', { name: 'Sign in', exact: true }).click()
  const status = (await response).status()
  if (status === 429) throw new QaFailure('QA_RATE_LIMITED')
  return status
}

async function assertSession(page: Page, username: string, role: 'USER' | 'ADMIN') {
  const result = await page.evaluate(async ({ expectedUsername, expectedRole }) => {
    const response = await fetch('/api/v1/auth/me', { credentials: 'include' })
    const body = await response.json()
    return {
      status: response.status,
      expectedUser: body.username === expectedUsername,
      expectedRole: Array.isArray(body.roles) && body.roles.includes(expectedRole),
    }
  }, { expectedUsername: username, expectedRole: role })
  expect(result).toEqual({ status: 200, expectedUser: true, expectedRole: true })
  await expect(page.getByRole('button', { name: `Account menu for ${username}`, exact: true })).toBeVisible()
}

async function assertCount(page: Page) {
  const result = await page.evaluate(async () => {
    const response = await fetch('/api/v1/products?page=0&size=1', { credentials: 'include' })
    const body = await response.json()
    return { status: response.status, count: body.totalElements }
  })
  expect(result).toEqual({ status: 200, count: 500 })
}

test('E2.anonymous-invalid', async ({ page }) => {
  for (const path of ['/products', '/dashboard']) {
    await page.goto(path)
    await expect(page).toHaveURL(`${UI_ORIGIN}/login`)
    await expect(page.getByRole('button', { name: 'Sign in', exact: true })).toBeVisible()
  }
  // Synthetic wrong value is generated in memory, never committed or logged.
  expect(await submitLogin(page, 'admin', randomUUID())).toBe(401)
  await expect(page.getByRole('alert')).toBeVisible()
  await expect(page).toHaveURL(`${UI_ORIGIN}/login`)
  await page.getByLabel(/^Password(?:\s*\*)?\s*$/).fill('')
})

test('E2.user-restore-logout', async ({ page, context }) => {
  const credentials = credentialsFor('USER')
  await page.goto('/login')
  expect(await submitLogin(page, 'user', credentials.password)).toBe(200)
  await expect(page).toHaveURL(`${UI_ORIGIN}/dashboard`)
  await assertSession(page, 'user', 'USER')
  await assertCount(page)
  const restored = page.waitForResponse(item => new URL(item.url()).pathname === '/api/v1/auth/me'
    && item.request().method() === 'GET')
  await page.reload()
  expect((await restored).status()).toBe(200)
  await assertSession(page, 'user', 'USER')
  const logout = page.waitForResponse(item => new URL(item.url()).pathname === '/api/v1/auth/logout'
    && item.request().method() === 'POST')
  await page.getByRole('button', { name: 'Account menu for user', exact: true }).click()
  await page.getByRole('menuitem', { name: 'Sign out', exact: true }).click()
  expect((await logout).status()).toBe(204)
  await expect(page).toHaveURL(`${UI_ORIGIN}/login`)
  // Inspect only cookie presence, never assert/print cookie values.
  expect((await context.cookies()).some(cookie => cookie.name === 'ACCESS_TOKEN')).toBe(false)
  expect(await page.evaluate(async () => (await fetch('/api/v1/auth/me', { credentials: 'include' })).status)).toBe(401)
  await page.goto('/products')
  await expect(page).toHaveURL(`${UI_ORIGIN}/login`)
})

test('E2.admin-restore-mid-session-401', async ({ page, context }) => {
  const credentials = credentialsFor('ADMIN')
  await page.goto('/login')
  expect(await submitLogin(page, 'admin', credentials.password)).toBe(200)
  await expect(page).toHaveURL(`${UI_ORIGIN}/dashboard`)
  await assertSession(page, 'admin', 'ADMIN')
  const restored = page.waitForResponse(item => new URL(item.url()).pathname === '/api/v1/auth/me'
    && item.request().method() === 'GET')
  await page.reload()
  expect((await restored).status()).toBe(200)
  await assertSession(page, 'admin', 'ADMIN')
  await assertCount(page)
  await expect(page.getByRole('img', { name: 'Bar chart showing product counts by category' })).toBeVisible()
  // Simulate session expiry in this isolated browser only; exercise a real 401.
  await context.clearCookies({ name: 'ACCESS_TOKEN' })
  const unauthorized = page.waitForResponse(item => new URL(item.url()).pathname === '/api/v1/products'
    && item.status() === 401)
  await page.getByRole('link', { name: 'Products', exact: true }).click()
  expect((await unauthorized).status()).toBe(401)
  await expect(page).toHaveURL(`${UI_ORIGIN}/login`)
  await expect(page.getByRole('button', { name: 'Sign in', exact: true })).toBeVisible()
})

import type { Page } from '@playwright/test'
import type { ProductPage } from '../src/api/client'
import { test as base, expect, credentialsFor } from './support/fixtures'
import { QaApi, QaFailure, UI_ORIGIN } from './support/qa-api'

const test = base.extend({
  adminApi: [async ({ browserName }, provide) => {
    if (browserName !== 'chromium') throw new QaFailure('QA_CAPTURE_ENABLED')
    const api = new QaApi('ADMIN', UI_ORIGIN)
    try { await provide(api) } finally { api.dispose() }
  }, { scope: 'worker' }],
})

async function assertCookieAndStorageIsolation(page: Page) {
  // Never return cookie or storage values to assertions/reporters.
  const metadata = await page.evaluate(() => {
    const visibleCookieNames = document.cookie.split(';').map(pair => pair.split('=', 1)[0].trim())
    const inspectStorage = (storage: Storage) => {
      let jwtValues = 0
      let authKeys = 0
      for (let index = 0; index < storage.length; index++) {
        const key = storage.key(index) ?? ''
        const value = storage.getItem(key) ?? ''
        if (/eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/.test(value)) jwtValues++
        if (/(?:password|jwt|access.?token|authorization)/i.test(key)) authKeys++
      }
      return { entries: storage.length, jwtValues, authKeys }
    }
    return {
      authCookieReadable: visibleCookieNames.includes('ACCESS_TOKEN'),
      jwtCookieReadable: /eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/.test(document.cookie),
      local: inspectStorage(localStorage), session: inspectStorage(sessionStorage),
    }
  })
  expect(metadata).toEqual({
    authCookieReadable: false, jwtCookieReadable: false,
    local: { entries: 0, jwtValues: 0, authKeys: 0 },
    session: { entries: 0, jwtValues: 0, authKeys: 0 },
  })
}

test('E8.cookie-storage-and-inert-xss', async ({ page, context, qaProducts, adminApi }) => {
  await context.route('**/*', route => new URL(route.request().url()).origin === UI_ORIGIN
    ? route.fallback() : route.abort('blockedbyclient'))
  await context.routeWebSocket('**/*', socket => {
    if (new URL(socket.url()).origin === 'ws://localhost:5173') socket.connectToServer()
    else socket.close()
  })
  let dialogs = 0
  let probeImageRequests = 0
  let browserProductWrites = 0
  page.on('dialog', dialog => { dialogs++; void dialog.dismiss().catch(() => {}) })
  page.on('request', request => {
    const url = new URL(request.url())
    if (request.resourceType() === 'image' && /(?:^|\/)x$/.test(url.pathname)) probeImageRequests++
    if (url.pathname.startsWith('/api/v1/products')
        && !['GET', 'HEAD', 'OPTIONS'].includes(request.method())) browserProductWrites++
  })
  const probeName = `${qaProducts.scope}-<img src=x onerror=alert(1)>`
  const product = await qaProducts.create({ ...qaProducts.input('xss'), name: probeName })
  expect(product.name).toBe(probeName)
  expect(await adminApi.totalProducts()).toBe(501)

  const credentials = credentialsFor('USER')
  await page.goto('/login')
  await page.getByLabel(/^Username(?:\s*\*)?\s*$/).fill('user')
  await page.getByLabel(/^Password(?:\s*\*)?\s*$/).fill(credentials.password)
  const login = page.waitForResponse(response => new URL(response.url()).pathname === '/api/v1/auth/login'
    && response.request().method() === 'POST')
  await page.getByRole('button', { name: 'Sign in', exact: true }).click()
  const status = (await login).status()
  if (status === 429) throw new QaFailure('QA_RATE_LIMITED')
  expect(status).toBe(200)
  await expect(page).toHaveURL(`${UI_ORIGIN}/dashboard`)
  await expect(page.getByRole('button', { name: 'Account menu for user', exact: true })).toBeVisible()
  const authCookie = (await context.cookies(UI_ORIGIN)).find(cookie => cookie.name === 'ACCESS_TOKEN')
  expect({
    present: Boolean(authCookie?.value), httpOnly: authCookie?.httpOnly === true,
    rootPath: authCookie?.path === '/', sameSiteLax: authCookie?.sameSite === 'Lax',
  }).toEqual({ present: true, httpOnly: true, rootPath: true, sameSiteLax: true })
  // Secure is intentionally not required over HTTP with the dev profile.
  await assertCookieAndStorageIsolation(page)
  await page.getByRole('link', { name: 'Products', exact: true }).click()

  for (const reload of [false, true]) {
    if (reload) await page.reload()
    const filtered = page.waitForResponse(response => {
      const url = new URL(response.url())
      return url.pathname === '/api/v1/products' && url.searchParams.get('category') === qaProducts.scope
        && response.request().method() === 'GET'
    })
    await page.getByRole('combobox', { name: 'Category', exact: true }).click()
    await page.getByRole('option', { name: qaProducts.scope, exact: true }).click()
    const response = await filtered
    expect(response.status()).toBe(200)
    const ownPage = await response.json() as ProductPage
    expect(ownPage.totalElements).toBe(1)
    expect(ownPage.content.map(item => item.id)).toEqual([product.id])
    const name = page.getByText(probeName, { exact: true })
    await expect(name).toBeVisible()
    await expect(name).toHaveText(probeName)
    expect(await name.evaluate(element => element.childElementCount)).toBe(0)
    const row = page.getByRole('table', { name: 'Product catalogue' }).getByRole('row').filter({ has: name })
    await expect(row).toHaveCount(1)
    await expect(row.locator('img, script, [onerror]')).toHaveCount(0)
    // Yield two rendering frames so an accidental image/error handler can surface.
    await page.evaluate(() => new Promise<void>(resolve => {
      requestAnimationFrame(() => requestAnimationFrame(() => resolve()))
    }))
    expect(dialogs).toBe(0)
    expect(probeImageRequests).toBe(0)
    await assertCookieAndStorageIsolation(page)
  }
  expect(browserProductWrites).toBe(0)
  expect(await adminApi.totalProducts()).toBe(501)
  // Independent finally cleanup removes only the probe and requires total=500.
})

// G1: node frontend/e2e/concurrency.mjs (requires the running backend only).
// Uses exported DEV_ADMIN_PASSWORD; never reads .env or persists authentication.
// Creates five qa-owned products, cleans up even after failed assertions, and
// compares the complete initial/final seeded inventory. Do not run concurrently
// with other writers. No packages, browsers, or service changes are required.
import { randomUUID } from 'node:crypto'
import { isDeepStrictEqual } from 'node:util'
import { QaCounter } from './support/qa-counter.mjs'

const origin = 'http://localhost:8080'
const scope = `qa-g1-${randomUUID()}`
const fields = ['name', 'description', 'category', 'price', 'stock', 'tags', 'specs', 'active']
const cookies = new Map()
const attemptedNames = new Set()
const knownIds = new Set()
const metrics = { createStatuses: new QaCounter(), updateStatuses: new QaCounter(), rounds: [], deleted: 0,
  csrfPairsChecked: 0, csrfCookieDeletions: 0 }
let baseline
let writesAttempted = false
let failure
let cleanupFailure
let stage = 'preflight'

class QaError extends Error {}
function check(value, code) { if (!value) throw new QaError(code) }
function safeError(error) {
  return error instanceof QaError ? error.message : 'QA_REQUEST_OR_RUNNER_FAILURE'
}
function writable(product) {
  return Object.fromEntries(fields.map(key => [key, product[key]]))
}
function owned(product) {
  return product?.category === scope && attemptedNames.has(product?.name)
}
function tally(bucket, status) { bucket.increment(status) }

function cookieHeader() {
  return [...cookies].map(([k, v]) => `${k}=${v}`).join('; ')
}

async function request(path, method = 'GET', body, writeSecurity) {
  check(path.startsWith('/api/v1/') || path === '/actuator/health', 'QA_INVALID_PATH')
  const headers = { Accept: 'application/json, application/problem+json' }
  if (body !== undefined) headers['Content-Type'] = 'application/json'
  if (method !== 'GET') {
    // Parallel callers supply the same immutable pair. Sequential writes obtain
    // a fresh pair after any preceding authenticated read/cookie rotation.
    const security = writeSecurity || await csrfPair()
    headers.Cookie = security.cookieHeader
    headers['X-XSRF-TOKEN'] = security.token
  } else if (cookies.size) headers.Cookie = cookieHeader()
  const response = await fetch(origin + path, {
    method, headers, redirect: 'error', signal: AbortSignal.timeout(8000),
    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
  })
  for (const cookie of response.headers.getSetCookie()) {
    const pair = cookie.split(';', 1)[0]
    const separator = pair.indexOf('=')
    if (separator > 0) {
      const name = pair.slice(0, separator)
      const value = pair.slice(separator + 1)
      const maxAge = cookie.match(/;\s*Max-Age=(-?\d+)/i)
      const expires = cookie.match(/;\s*Expires=([^;]+)/i)
      if (!value || (maxAge ? Number(maxAge[1]) <= 0 : expires && Date.parse(expires[1]) <= Date.now())) {
        cookies.delete(name)
        if (name === 'XSRF-TOKEN') metrics.csrfCookieDeletions++
      } else cookies.set(name, value)
    }
  }
  check(response.status !== 429, 'QA_RATE_LIMITED_NO_WAIT')
  const result = { status: response.status, type: response.headers.get('content-type') || '', body: null }
  if (response.status !== 204) {
    try { result.body = await response.json() } catch { throw new QaError('QA_NON_JSON_RESPONSE') }
  }
  if (response.status === 403) {
    console.log(JSON.stringify({ stage, deniedMethod: method, status: 403,
      problemDetail: result.type.includes('application/problem+json') && result.body?.status === 403 }))
  }
  return result
}

async function csrfPair() {
  const result = await request('/api/v1/auth/csrf')
  check(result.status === 200 && typeof result.body?.token === 'string', 'QA_CSRF_FAILED')
  const diagnostics = { stage, csrfCookiePresent: Boolean(cookies.get('XSRF-TOKEN')),
    authCookiePresent: Boolean(cookies.get('ACCESS_TOKEN')),
    headerMatchesCookie: result.body.token === cookies.get('XSRF-TOKEN') }
  console.log(JSON.stringify({ csrfCheck: diagnostics }))
  check(diagnostics.csrfCookiePresent && diagnostics.headerMatchesCookie, 'QA_CSRF_PAIR_MISMATCH')
  if (stage !== 'preflight') check(diagnostics.authCookiePresent, 'QA_AUTH_COOKIE_MISSING')
  metrics.csrfPairsChecked++
  return Object.freeze({ cookieHeader: cookieHeader(), token: result.body.token })
}

async function inventory(expected) {
  const result = []
  for (let page = 0; page < Math.ceil(expected / 100); page++) {
    const response = await request(`/api/v1/products?page=${page}&size=100&sort=id,asc`)
    check(response.status === 200 && response.body.totalElements === expected
      && response.body.content.length === Math.min(100, expected - page * 100), 'QA_INVENTORY_COUNT_CHANGED')
    result.push(...response.body.content)
  }
  check(result.length === expected && new Set(result.map(item => item.id)).size === expected,
    'QA_INVENTORY_UNSTABLE')
  return result
}

async function parallel(actions) {
  // Await every in-flight request before validating results or entering cleanup.
  const results = await Promise.allSettled(actions.map(action => action()))
  const rejected = results.find(result => result.status === 'rejected')
  if (rejected) throw rejected.reason
  return results.map(result => result.value)
}

function verifySaved(saved, input, expectedVersion, id) {
  check(owned(saved) && isDeepStrictEqual(writable(saved), writable(input)), 'QA_FIELDS_CORRUPTED')
  check(/^[a-f0-9]{24}$/i.test(saved.id) && (!id || saved.id === id)
    && saved.version === expectedVersion, 'QA_ID_OR_VERSION_INVALID')
  check(Number.isFinite(Date.parse(saved.createdAt)) && Number.isFinite(Date.parse(saved.updatedAt))
    && Date.parse(saved.updatedAt) >= Date.parse(saved.createdAt), 'QA_TIMESTAMPS_INVALID')
}

function conflict(response) {
  check(response.status === 409 && response.type.includes('application/problem+json')
    && response.body?.status === 409 && typeof response.body.title === 'string', 'QA_CONFLICT_CONTRACT_FAILED')
  check(!/stackTrace|com\.vaibhav|org\.springframework|java\.lang|\bat\s+\S+\(/.test(JSON.stringify(response.body)),
    'QA_CONFLICT_LEAK')
}

async function cleanup() {
  // Discover successful POSTs even when their response was lost. Never delete by
  // prefix alone: each record must match this run's category and attempted name.
  const found = await request(`/api/v1/products?size=100&category=${encodeURIComponent(scope)}`)
  check(found.status === 200 && found.body.totalElements <= 5, 'QA_CLEANUP_DISCOVERY_FAILED')
  check(found.body.content.length === found.body.totalElements, 'QA_CLEANUP_INCOMPLETE_DISCOVERY')
  for (const product of found.body.content) {
    check(owned(product), 'QA_CLEANUP_FOREIGN_PRODUCT')
    knownIds.add(product.id)
  }
  for (const id of knownIds) {
    const path = `/api/v1/products/${encodeURIComponent(id)}`
    const read = await request(path)
    if (read.status === 404) continue
    check(read.status === 200 && owned(read.body), 'QA_CLEANUP_FOREIGN_PRODUCT')
    check((await request(path, 'DELETE')).status === 204, 'QA_CLEANUP_DELETE_FAILED')
    metrics.deleted++
    check((await request(path)).status === 404, 'QA_CLEANUP_RECORD_REMAINS')
  }
  const final = await inventory(500)
  check(isDeepStrictEqual(final, baseline), 'QA_SEEDED_INVENTORY_CHANGED')
  check(!final.some(item => item.name?.startsWith('qa-') || item.category?.startsWith('qa-')), 'QA_RECORDS_REMAIN')
  return { totalElements: final.length, qaRecords: 0, seededRecordsUnchanged: true }
}

try {
  check(Boolean(process.env.DEV_ADMIN_PASSWORD), 'QA_MISSING_DEV_ADMIN_PASSWORD')
  const health = await request('/actuator/health')
  check(health.status === 200 && health.body?.status === 'UP', 'QA_BACKEND_NOT_HEALTHY')
  const login = await request('/api/v1/auth/login', 'POST', {
    username: process.env.DEV_ADMIN_USERNAME || 'admin', password: process.env.DEV_ADMIN_PASSWORD,
  })
  check(login.status === 200 && login.body?.roles?.includes('ADMIN'), 'QA_ADMIN_LOGIN_FAILED')
  baseline = await inventory(500)
  check(!baseline.some(item => item.name?.startsWith('qa-') || item.category?.startsWith('qa-')),
    'QA_EXISTING_QA_RECORDS')
  console.log(JSON.stringify({ stage, totalElements: 500, qaRecords: 0 }))

  stage = 'parallel-creates'
  const inputs = Array.from({ length: 5 }, (_, index) => ({
    name: `${scope}-product-${index}`, description: `QA concurrency fixture ${index}`,
    category: scope, price: 20.25 + index, stock: index + 1, tags: ['qa', `batch-${index}`],
    specs: { dimensions: { width: index + 1, unit: 'cm' }, material: `qa-material-${index}` },
    active: index % 2 === 0,
  }))
  for (const input of inputs) attemptedNames.add(input.name)
  const createSecurity = await csrfPair()
  writesAttempted = true
  const created = await parallel(inputs.map(input => async () => {
    const response = await request('/api/v1/products', 'POST', input, createSecurity)
    tally(metrics.createStatuses, response.status)
    if (response.status === 201 && owned(response.body)) knownIds.add(response.body.id)
    return response
  }))
  for (let index = 0; index < created.length; index++) {
    check(created[index].status === 201, 'QA_PARALLEL_CREATE_FAILED')
    verifySaved(created[index].body, inputs[index], 0)
    const read = await request(`/api/v1/products/${encodeURIComponent(created[index].body.id)}`)
    check(read.status === 200, 'QA_CREATE_READ_FAILED')
    verifySaved(read.body, inputs[index], 0, created[index].body.id)
    check(Date.parse(read.body.createdAt) === Date.parse(created[index].body.createdAt)
      && Date.parse(read.body.updatedAt) === Date.parse(created[index].body.updatedAt), 'QA_CREATE_AUDIT_MISMATCH')
  }
  check(knownIds.size === 5, 'QA_DUPLICATE_CREATE_IDS')
  const withFixtures = await inventory(505)
  check(withFixtures.filter(owned).length === 5
    && isDeepStrictEqual(withFixtures.filter(item => !owned(item)), baseline), 'QA_CREATE_INVENTORY_CORRUPTED')
  console.log(JSON.stringify({ stage, statuses: metrics.createStatuses, uniqueIds: knownIds.size, totalElements: 505 }))

  const path = `/api/v1/products/${encodeURIComponent(created[0].body.id)}`
  for (let round = 1; round <= 3; round++) {
    stage = `competing-updates-${round}`
    const initial = await request(path)
    check(initial.status === 200, 'QA_UPDATE_SNAPSHOT_FAILED')
    const snapshot = initial.body
    const updates = Array.from({ length: 8 }, (_, index) => ({
      ...writable(snapshot), version: snapshot.version,
      description: `QA round ${round} contender ${index}`, price: 100 + round * 10 + index + 0.25,
      stock: round * 100 + index, tags: ['qa', `round-${round}`, `contender-${index}`],
      specs: { dimensions: { width: round * 10 + index, unit: 'cm' }, material: `qa-${round}-${index}` },
      active: index % 2 === 0,
    }))
    const updateSecurity = await csrfPair()
    const responses = await parallel(updates.map(input => async () => {
      const response = await request(path, 'PUT', input, updateSecurity)
      tally(metrics.updateStatuses, response.status)
      return response
    }))
    const winners = responses.map((response, index) => response.status === 200 ? index : -1).filter(index => index >= 0)
    check(winners.length === 1, 'QA_NOT_EXACTLY_ONE_UPDATE_WINNER')
    for (const response of responses) if (response.status !== 200) conflict(response)
    const winner = winners[0]
    verifySaved(responses[winner].body, updates[winner], snapshot.version + 1, snapshot.id)
    const read = await request(path)
    check(read.status === 200, 'QA_UPDATE_READ_FAILED')
    verifySaved(read.body, updates[winner], snapshot.version + 1, snapshot.id)
    check(read.body.createdAt === snapshot.createdAt
      && Date.parse(read.body.updatedAt) >= Date.parse(snapshot.updatedAt)
      && Date.parse(read.body.updatedAt) === Date.parse(responses[winner].body.updatedAt), 'QA_UPDATE_AUDIT_MISMATCH')
    // Explicit replay after all parallel responses: conflict must not mutate any field.
    conflict(await request(path, 'PUT', updates[winner]))
    const afterReplay = await request(path)
    check(afterReplay.status === 200 && isDeepStrictEqual(afterReplay.body, read.body), 'QA_REPLAY_MUTATED_PRODUCT')
    metrics.rounds.push({ round, attempted: 8, success: 1, conflicts: 7, version: read.body.version, staleReplay: 409 })
    console.log(JSON.stringify({ stage, ...metrics.rounds.at(-1) }))
  }

  const after = await inventory(505)
  check(isDeepStrictEqual(after.filter(item => !owned(item)), baseline), 'QA_CONCURRENCY_CHANGED_SEEDED_RECORDS')
  for (let index = 1; index < created.length; index++) {
    const product = after.find(item => item.id === created[index].body.id)
    verifySaved(product, inputs[index], 0, created[index].body.id)
    check(Date.parse(product.createdAt) === Date.parse(created[index].body.createdAt)
      && Date.parse(product.updatedAt) === Date.parse(created[index].body.updatedAt), 'QA_UNRELATED_FIXTURE_CHANGED')
  }
} catch (error) {
  failure = { stage, code: safeError(error) }
  console.log(JSON.stringify({ failure }))
} finally {
  if (writesAttempted) {
    try { console.log(JSON.stringify({ stage: 'cleanup', ...await cleanup() })) }
    catch (error) {
      cleanupFailure = safeError(error)
      console.log(JSON.stringify({ cleanupFailure }))
    }
  }
  cookies.clear()
}

console.log(JSON.stringify({ item: 'G1', status: failure || cleanupFailure ? 'FAILED' : 'PASSED', ...metrics }))
if (failure || cleanupFailure) process.exitCode = 1

import type { Locator, Page } from '@playwright/test'
import type { CategoryStats } from '../src/api/client'
import { test, expect, credentialsFor } from './support/fixtures'
import { QaFailure, UI_ORIGIN } from './support/qa-api'

function metric(page: Page, label: string): Locator {
  return page.locator('.metric-card').filter({ has: page.getByText(label, { exact: true }) }).locator('.metric-value')
}

function statsResponse(page: Page) {
  return page.waitForResponse(response => new URL(response.url()).pathname === '/api/v1/products/stats'
    && response.request().method() === 'GET')
}

async function expectedLabels(page: Page, stats: CategoryStats[]) {
  return page.evaluate(items => {
    const total = items.reduce((sum, item) => sum + item.count, 0)
    const price = (value: number) => new Intl.NumberFormat(undefined, {
      minimumFractionDigits: 2, maximumFractionDigits: 2,
    }).format(value)
    return {
      total: total.toLocaleString(), categories: String(items.length),
      weighted: price(total ? items.reduce((sum, item) => sum + item.count * item.averagePrice, 0) / total : 0),
      counts: items.map(item => `${item.count.toLocaleString()} items`),
      averages: items.map(item => price(item.averagePrice)),
    }
  }, stats)
}

async function assertMetrics(page: Page, stats: CategoryStats[]) {
  const labels = await expectedLabels(page, stats)
  await expect(metric(page, 'PRODUCTS IN CATALOGUE')).toHaveText(labels.total)
  await expect(metric(page, 'CATEGORIES')).toHaveText(labels.categories)
  await expect(metric(page, 'WEIGHTED AVERAGE PRICE')).toHaveText(labels.weighted)
  return labels
}

test('E7.dashboard-live-charts-empty-error', async ({ page, context }) => {
  await context.route('**/*', route => new URL(route.request().url()).origin === UI_ORIGIN
    ? route.fallback() : route.abort('blockedbyclient'))
  await context.routeWebSocket('**/*', socket => {
    if (new URL(socket.url()).origin === 'ws://localhost:5173') socket.connectToServer()
    else socket.close()
  })
  let productWrites = 0
  page.on('request', request => {
    if (new URL(request.url()).pathname.startsWith('/api/v1/products')
        && !['GET', 'HEAD', 'OPTIONS'].includes(request.method())) productWrites++
  })
  let mode: 'live' | 'empty' | 'error' = 'live'
  await page.route(url => url.origin === UI_ORIGIN && url.pathname === '/api/v1/products/stats', async route => {
    if (route.request().method() !== 'GET' || mode === 'live') return route.fallback()
    return route.fulfill(mode === 'empty'
      ? { status: 200, contentType: 'application/json', body: '[]' }
      : { status: 500, contentType: 'application/problem+json', body: JSON.stringify({
        type: 'about:blank', title: 'Internal Server Error', status: 500, detail: 'qa-dashboard-service-unavailable',
      }) })
  })

  const credentials = credentialsFor('USER')
  await page.goto('/login')
  await page.getByLabel(/^Username(?:\s*\*)?\s*$/).fill('user')
  await page.getByLabel(/^Password(?:\s*\*)?\s*$/).fill(credentials.password)
  const login = page.waitForResponse(response => new URL(response.url()).pathname === '/api/v1/auth/login'
    && response.request().method() === 'POST')
  const initialStats = statsResponse(page)
  await page.getByRole('button', { name: 'Sign in', exact: true }).click()
  const loginStatus = (await login).status()
  if (loginStatus === 429) throw new QaFailure('QA_RATE_LIMITED')
  expect(loginStatus).toBe(200)
  await expect(page).toHaveURL(`${UI_ORIGIN}/dashboard`)
  const statsResult = await initialStats
  expect(statsResult.status()).toBe(200)
  const stats = await statsResult.json() as CategoryStats[]
  expect(stats.length).toBeGreaterThan(0)
  expect(stats.reduce((sum, item) => sum + item.count, 0)).toBe(500)
  expect(stats.every(item => Number.isInteger(item.count) && item.count > 0
    && Number.isFinite(item.averagePrice) && item.averagePrice > 0)).toBe(true)
  const countChart = page.getByRole('img', { name: 'Bar chart showing product counts by category', exact: true })
  const averageChart = page.getByRole('img', { name: 'Bar chart showing average prices by category', exact: true })

  await test.step('live metrics and every category tooltip match the API', async () => {
    const labels = await assertMetrics(page, stats)
    for (const [chart, values] of [[countChart, labels.counts], [averageChart, labels.averages]] as const) {
      await expect(chart).toBeVisible()
      const bars = chart.locator('.recharts-bar-rectangle')
      await expect(bars).toHaveCount(stats.length)
      for (const [index, item] of stats.entries()) {
        await bars.nth(index).hover()
        const tooltip = chart.locator('.recharts-tooltip-wrapper')
        await expect(tooltip).toBeVisible()
        await expect(tooltip.locator('.recharts-tooltip-label')).toHaveText(item.category)
        await expect(tooltip.locator('.recharts-tooltip-item-value')).toHaveText(values[index])
      }
    }
    await expect(page.getByRole('alert')).toHaveCount(0)
  })

  await test.step('empty response renders both chart placeholders', async () => {
    mode = 'empty'
    const emptyStats = statsResponse(page)
    await page.reload()
    expect((await emptyStats).status()).toBe(200)
    await assertMetrics(page, [])
    await expect(page.getByText('No category data to chart yet.', { exact: true })).toHaveCount(2)
    await expect(countChart).toHaveCount(0)
    await expect(averageChart).toHaveCount(0)
    await expect(page.getByRole('alert')).toHaveCount(0)
  })

  await test.step('error is visible and retry restores live statistics', async () => {
    mode = 'error'
    await page.reload()
    await expect(page.getByRole('alert')).toContainText('qa-dashboard-service-unavailable')
    await expect(page.getByRole('button', { name: 'Try again', exact: true })).toBeVisible()
    mode = 'live'
    const retried = statsResponse(page)
    await page.getByRole('button', { name: 'Try again', exact: true }).click()
    const response = await retried
    expect(response.status()).toBe(200)
    const recovered = await response.json() as CategoryStats[]
    expect(recovered).toEqual(stats)
    await assertMetrics(page, recovered)
    await expect(countChart.locator('.recharts-bar-rectangle')).toHaveCount(recovered.length)
    await expect(averageChart.locator('.recharts-bar-rectangle')).toHaveCount(recovered.length)
    await expect(page.getByRole('alert')).toHaveCount(0)
    await expect(page.getByText('No category data to chart yet.', { exact: true })).toHaveCount(0)
  })

  const final = await page.evaluate(async () => {
    const response = await fetch('/api/v1/products?page=0&size=1', { credentials: 'include' })
    const body = await response.json()
    return { status: response.status, count: body.totalElements }
  })
  expect(final).toEqual({ status: 200, count: 500 })
  expect(productWrites).toBe(0)
})

