    return url.pathname === '/api/v1/products' && url.searchParams.get('category') === qaProducts.scope
      && response.request().method() === 'GET'
  })
  await page.getByRole('combobox', { name: 'Category', exact: true }).click()
  await page.getByRole('option', { name: qaProducts.scope, exact: true }).click()
  const filteredResponse = await filtered
  expect(filteredResponse.status()).toBe(200)
  const ownPage = await filteredResponse.json() as ProductPage
  expect(ownPage.totalElements).toBe(1)
  expect(ownPage.content.map(item => item.id)).toEqual([product.id])
  const remove = page.getByRole('button', { name: `Delete ${product.name}`, exact: true })
  await expect(remove).toBeVisible()
  const dialog = page.getByRole('dialog', { name: 'Remove this product?', exact: true })

  await test.step('cancel preserves the product and sends no DELETE', async () => {
    await remove.click()
    await expect(dialog).toBeVisible()
    await expect(dialog).toContainText(product.name)
    await dialog.getByRole('button', { name: 'Keep product', exact: true }).click()
    await expect(dialog).not.toBeVisible()
    await expect(remove).toBeVisible()
    expect(deletedIds).toHaveLength(0)
    expect(await adminApi.product(product.id)).toMatchObject({
      id: product.id, name: product.name, version: product.version,
    })
    expect(await adminApi.totalProducts()).toBe(501)
  })

  await test.step('confirmation deletes once and refreshes the list', async () => {
    await remove.click()
    await expect(dialog).toBeVisible()
    const deleted = page.waitForResponse(response => new URL(response.url()).pathname ===
      `/api/v1/products/${encodeURIComponent(product.id)}` && response.request().method() === 'DELETE')
    const refreshed = page.waitForResponse(response => {
      const url = new URL(response.url())
      return url.pathname === '/api/v1/products' && url.searchParams.get('category') === qaProducts.scope
        && response.request().method() === 'GET'
    })
    await dialog.getByRole('button', { name: 'Remove product', exact: true }).click()
    expect((await deleted).status()).toBe(204)
    const refreshedResponse = await refreshed
    expect(refreshedResponse.status()).toBe(200)
    const empty = await refreshedResponse.json() as ProductPage
    expect(empty.totalElements).toBe(0)
    expect(empty.content).toHaveLength(0)
    await expect(dialog).not.toBeVisible()
    await expect(remove).toHaveCount(0)
    await expect(page.getByText('Nothing in this view yet', { exact: true })).toBeVisible()
    expect(deletedIds).toEqual([product.id])
    expect(await adminApi.product(product.id)).toBeNull()
    expect(await adminApi.totalProducts()).toBe(500)
    expect(await page.evaluate(async id => (await fetch(`/api/v1/products/${encodeURIComponent(id)}`,
      { credentials: 'include' })).status, product.id)).toBe(404)
    const unfiltered = page.waitForResponse(response => {
      const url = new URL(response.url())
      return url.pathname === '/api/v1/products' && !url.searchParams.has('category')
        && response.request().method() === 'GET'
    })
    await page.getByRole('button', { name: 'Clear', exact: true }).click()
    const restored = await unfiltered
    expect(restored.status()).toBe(200)
    expect((await restored.json() as ProductPage).totalElements).toBe(500)
    await expect(page.getByText('1–10 of 500', { exact: true })).toBeVisible()
    await expect(page.getByRole('table', { name: 'Product catalogue' }).getByRole('row')).toHaveCount(11)
  })
  // Independent finally cleanup also handles failures before UI confirmation.
})

// G2: node frontend/e2e/load-smoke.mjs (running backend, exported ADMIN password).
// No dependencies, service management, product writes, .env reads, or recordings.
// Fixed localhost-only, closed-loop smoke: 20 workers, 60s, 1s think time.
// Uses one shared ADMIN identity, not 20 distinct accounts. Not a capacity SLA.
import { performance } from 'node:perf_hooks'
import { setTimeout as delay } from 'node:timers/promises'
import { isDeepStrictEqual } from 'node:util'
import { QaCounter } from './support/qa-counter.mjs'

const origin = 'http://localhost:8080'
const listPath = '/api/v1/products?page=0&size=20&sort=id,asc'
const virtualUsers = 20
const durationMs = 60_000
const thinkTimeMs = 1_000
const cookies = new Map()
const latencies = []
const statuses = new QaCounter()
const errors = new QaCounter()
const perWorker = Array(virtualUsers).fill(0)
let baseline
let expectedPage
let loadCookie
let stop = false
let failure
let finalInventory
let timer
let stage = 'preflight'
let loadElapsedMs = 0

class QaError extends Error {}
function check(condition, code) { if (!condition) throw new QaError(code) }
function safeError(error) { return error instanceof QaError ? error.message : 'QA_REQUEST_OR_RUNNER_FAILURE' }
function tally(bucket, key) { bucket.increment(key) }
function cookieHeader() { return [...cookies].map(([key, value]) => `${key}=${value}`).join('; ') }
function percentile(sorted, fraction) {
  return sorted.length ? sorted[Math.max(0, Math.ceil(sorted.length * fraction) - 1)] : null
}

async function request(path, method = 'GET', body, token) {
  check(path.startsWith('/api/v1/') || path === '/actuator/health', 'QA_INVALID_PATH')
  const response = await fetch(origin + path, {
    method, redirect: 'error', signal: AbortSignal.timeout(5000),
    headers: { Accept: 'application/json, application/problem+json',
      ...(cookies.size ? { Cookie: cookieHeader() } : {}),
      ...(body === undefined ? {} : { 'Content-Type': 'application/json' }),
      ...(token ? { 'X-XSRF-TOKEN': token } : {}) },
    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
  })
  for (const header of response.headers.getSetCookie()) {
    const pair = header.split(';', 1)[0]
    const separator = pair.indexOf('=')
    if (separator < 1) continue
    const name = pair.slice(0, separator)
    const value = pair.slice(separator + 1)
    const maxAge = header.match(/;\s*Max-Age=(-?\d+)/i)
    const expires = header.match(/;\s*Expires=([^;]+)/i)
    if (!value || (maxAge ? Number(maxAge[1]) <= 0 : expires && Date.parse(expires[1]) <= Date.now())) {
      cookies.delete(name)
    } else cookies.set(name, value)
  }
  check(response.status !== 429, 'QA_RATE_LIMITED_NO_WAIT')
  let json
  try { json = await response.json() } catch { throw new QaError('QA_NON_JSON_RESPONSE') }
  return { status: response.status, body: json }
}

async function inventory() {
  const all = []
  for (let page = 0; page < 5; page++) {
    const response = await request(`/api/v1/products?page=${page}&size=100&sort=id,asc`)
    check(response.status === 200 && response.body.totalElements === 500
      && response.body.content.length === 100, 'QA_INVENTORY_COUNT_INVALID')
    all.push(...response.body.content)
  }
  check(new Set(all.map(product => product.id)).size === 500, 'QA_INVENTORY_UNSTABLE')
  check(!all.some(product => product.name?.startsWith('qa-') || product.category?.startsWith('qa-')),
    'QA_EXISTING_QA_RECORDS')
  return all
}

async function worker(index, deadline) {
  while (!stop && performance.now() < deadline) {
    const start = performance.now()
    let errorCode
    try {
      // Never log the cookie/header/body; all workers reuse one immutable login.
      const response = await fetch(origin + listPath, {
        headers: { Accept: 'application/json', Cookie: loadCookie },
        redirect: 'error', signal: AbortSignal.timeout(5000),
      })
      tally(statuses, response.status)
      const body = await response.json()
      if (response.status !== 200) errorCode = `HTTP_${response.status}`
      else if (!isDeepStrictEqual(body, expectedPage)) errorCode = 'INVALID_OR_CHANGED_PAGE'
    } catch (error) {
      errorCode = error?.name === 'TimeoutError' ? 'TIMEOUT' : 'REQUEST_OR_JSON_ERROR'
    }
    latencies.push(performance.now() - start)
    perWorker[index]++
    if (errorCode) {
      tally(errors, errorCode)
      stop = true // Drain in-flight requests; do not hammer a failing backend.
    }
    const remaining = deadline - performance.now()
    if (!stop && remaining > 0) await delay(Math.min(thinkTimeMs, remaining))
  }
}

try {
  check(Boolean(process.env.DEV_ADMIN_PASSWORD), 'QA_MISSING_DEV_ADMIN_PASSWORD')
  const health = await request('/actuator/health')
  check(health.status === 200 && health.body?.status === 'UP', 'QA_BACKEND_NOT_HEALTHY')
  const csrf = await request('/api/v1/auth/csrf')
  check(csrf.status === 200 && typeof csrf.body?.token === 'string'
    && csrf.body.token === cookies.get('XSRF-TOKEN'), 'QA_CSRF_PAIR_INVALID')
  const login = await request('/api/v1/auth/login', 'POST', {
    username: process.env.DEV_ADMIN_USERNAME || 'admin', password: process.env.DEV_ADMIN_PASSWORD,
  }, csrf.body.token)
  check(login.status === 200 && login.body?.roles?.includes('ADMIN'), 'QA_ADMIN_LOGIN_FAILED')
  check(Boolean(cookies.get('ACCESS_TOKEN')), 'QA_AUTH_COOKIE_MISSING')
  loadCookie = `ACCESS_TOKEN=${cookies.get('ACCESS_TOKEN')}`
  baseline = await inventory()
  const list = await request(listPath)
  check(list.status === 200 && list.body?.totalElements === 500 && list.body.content.length === 20
    && isDeepStrictEqual(list.body.content, baseline.slice(0, 20)), 'QA_LIST_PREFLIGHT_FAILED')
  expectedPage = list.body
  console.log(JSON.stringify({ stage, totalElements: 500, qaRecords: 0, virtualUsers,
    durationSeconds: durationMs / 1000, thinkTimeMs, logins: 1, productWrites: 0 }))

  stage = 'load'
  const start = performance.now()
  const deadline = start + durationMs
  timer = setInterval(() => console.log(JSON.stringify({ stage, elapsedSeconds: Math.round((performance.now() - start) / 1000),
    requests: latencies.length, errors: errors.total() })), 20_000)
  const settled = await Promise.allSettled(Array.from({ length: virtualUsers }, (_, index) => worker(index, deadline)))
  loadElapsedMs = performance.now() - start
  clearInterval(timer)
  check(settled.every(result => result.status === 'fulfilled'), 'QA_WORKER_FAILURE')
  check(!stop && loadElapsedMs >= durationMs && perWorker.every(count => count > 0), 'QA_LOAD_INTERRUPTED')
  check(errors.size === 0, 'QA_LOAD_ERRORS')
} catch (error) {
  failure = { stage, code: safeError(error) }
  console.log(JSON.stringify({ failure }))
} finally {
  clearInterval(timer)
  if (baseline) {
    try {
      const after = await inventory()
      check(isDeepStrictEqual(after, baseline), 'QA_SEEDED_INVENTORY_CHANGED')
      finalInventory = { totalElements: 500, qaRecords: 0, seededRecordsUnchanged: true }
      console.log(JSON.stringify({ stage: 'final-inventory', ...finalInventory }))
    } catch (error) {
      failure ||= { stage: 'final-inventory', code: safeError(error) }
      console.log(JSON.stringify({ finalInventoryFailure: safeError(error) }))
    }
  }
  cookies.clear()
  loadCookie = undefined
}

const sorted = [...latencies].sort((a, b) => a - b)
const failedRequests = errors.total()
const rounded = value => value === null ? null : Number(value.toFixed(2))
console.log(JSON.stringify({ item: 'G2', status: failure ? 'FAILED' : 'PASSED',
  virtualUsers, elapsedSeconds: rounded(loadElapsedMs / 1000), requests: latencies.length,
  requestsPerSecond: loadElapsedMs ? rounded(latencies.length * 1000 / loadElapsedMs) : null,
  latencyMs: { p50: rounded(percentile(sorted, 0.50)), p95: rounded(percentile(sorted, 0.95)),
    p99: rounded(percentile(sorted, 0.99)), max: rounded(sorted.at(-1) ?? null) },
  failedRequests, errorRatePercent: latencies.length ? rounded(failedRequests * 100 / latencies.length) : null,
  statuses, errors, perWorkerRequests: { min: Math.min(...perWorker), max: Math.max(...perWorker) },
  finalInventoryVerified: Boolean(finalInventory), productWrites: 0 }))
if (failure) process.exitCode = 1

// G3: node frontend/e2e/mongo-outage.mjs --approved-stop
// DESTRUCTIVE TO AVAILABILITY: requires explicit QA approval for every run.
// Stops/restarts only this checkout's existing Mongo container, never volumes.
// One env-var ADMIN login; localhost reads only; no .env reads or recordings.
import { execFile } from 'node:child_process'
import { promisify, isDeepStrictEqual } from 'node:util'
import { fileURLToPath } from 'node:url'
import { performance } from 'node:perf_hooks'
import { setTimeout as delay } from 'node:timers/promises'

const execute = promisify(execFile)
const root = fileURLToPath(new URL('../../', import.meta.url)).replace(/\/$/, '')
const origin = 'http://localhost:8080'
const cookies = new Map()
const metrics = { productWrites: 0, logins: 0, outage: {}, recovery: null }
let container
let mounts
let baseline
let stopAttempted = false
let failure
let recoveryFailure
let stage = 'preflight'

class QaError extends Error {}
function check(condition, code) { if (!condition) throw new QaError(code) }
function safeError(error) { return error instanceof QaError ? error.message : 'QA_OPERATION_FAILED' }
async function docker(args, timeout = 15_000) {
  const result = await execute('docker', args, { timeout, maxBuffer: 32_768 })
  return result.stdout.trim()
}

async function state() {
  // Select individual metadata fields; never inspect Env or healthcheck output.
  const format = '{{.State.Running}}|{{if .State.Health}}{{.State.Health.Status}}{{end}}|'
    + '{{index .Config.Labels "com.docker.compose.project.working_dir"}}|'
    + '{{index .Config.Labels "com.docker.compose.service"}}|{{json .Mounts}}'
  const [running, health, directory, service, json] = (await docker(['inspect', '--format', format, container])).split('|')
  check(directory === root && service === 'mongodb', 'QA_WRONG_CONTAINER')
  const volumes = JSON.parse(json).map(mount => ({ type: mount.Type, name: mount.Name, destination: mount.Destination }))
  check(volumes.some(mount => mount.type === 'volume' && mount.destination === '/data/db' && mount.name),
    'QA_NAMED_VOLUME_MISSING')
  return { running: running === 'true', health, volumes }
}

async function request(path, { method = 'GET', body, token, timeout = 8000, anonymous = false } = {}) {
  check(path.startsWith('/api/v1/') || path === '/actuator/health', 'QA_INVALID_PATH')
  const started = performance.now()
  const response = await fetch(origin + path, {
    method, redirect: 'error', signal: AbortSignal.timeout(timeout),
    headers: { Accept: 'application/json, application/problem+json',
      ...(!anonymous && cookies.size ? { Cookie: [...cookies].map(([k, v]) => `${k}=${v}`).join('; ') } : {}),
      ...(token ? { 'X-XSRF-TOKEN': token } : {}),
      ...(body === undefined ? {} : { 'Content-Type': 'application/json' }) },
    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
  })
  for (const header of response.headers.getSetCookie()) {
    const pair = header.split(';', 1)[0]
    const separator = pair.indexOf('=')
    if (separator < 1) continue
    const name = pair.slice(0, separator)
    const value = pair.slice(separator + 1)
    const maxAge = header.match(/;\s*Max-Age=(-?\d+)/i)
    if (!value || (maxAge && Number(maxAge[1]) <= 0)) cookies.delete(name)
    else cookies.set(name, value)
  }
  check(response.status !== 429, 'QA_RATE_LIMITED_NO_WAIT')
  let json
  try { json = await response.json() } catch { throw new QaError('QA_NON_JSON_RESPONSE') }
  return { status: response.status, type: response.headers.get('content-type') || '', body: json,
    elapsedMs: Math.round(performance.now() - started) }
}

function sanitized(body) {
  const text = JSON.stringify(body)
  const secretMatch = ['DEV_ADMIN_PASSWORD', 'DEV_USER_PASSWORD']
    .some(key => process.env[key] && text.includes(process.env[key]))
  return !secretMatch && !/eyJ[A-Za-z0-9_-]{8,}|mongodb(?:\+srv)?:\/\/|27017|localhost|127\.0\.0\.1|stackTrace|\bstack\b|com\.vaibhav|org\.springframework|com\.mongodb|java\.lang|Mongo\w*Exception|\bat\s+\S+\(/i.test(text)
}

function health(response, status, http) {
  check(response.status === http && response.body?.status === status, 'QA_HEALTH_STATUS_INVALID')
  check(Object.keys(response.body).every(key => ['status', 'groups'].includes(key))
    && sanitized(response.body), 'QA_HEALTH_DETAILS_LEAK')
}

async function inventory() {
  const all = []
  for (let page = 0; page < 5; page++) {
    const response = await request(`/api/v1/products?page=${page}&size=100&sort=id,asc`)
    check(response.status === 200 && response.body.totalElements === 500
      && response.body.content.length === 100, 'QA_INVENTORY_COUNT_INVALID')
    all.push(...response.body.content)
  }
  check(new Set(all.map(product => product.id)).size === 500, 'QA_INVENTORY_UNSTABLE')
  check(!all.some(product => product.name?.startsWith('qa-') || product.category?.startsWith('qa-')),
    'QA_RECORDS_REMAIN')
  return all
}

async function restore() {
  const started = performance.now()
  await docker(['start', container], 20_000)
  console.log(JSON.stringify({ stage: 'recovery', containerStartRequested: true }))
  const deadline = performance.now() + 60_000
  let recovered = false
  while (performance.now() < deadline) {
    const current = await state()
    check(isDeepStrictEqual(current.volumes, mounts), 'QA_VOLUME_CHANGED')
    if (current.running && current.health === 'healthy') {
      try {
        const response = await request('/actuator/health', { anonymous: true })
        health(response, 'UP', 200)
        recovered = true
        break
      } catch (error) {
        if (error instanceof QaError && error.message === 'QA_HEALTH_DETAILS_LEAK') throw error
      }
    }
    await delay(2000)
  }
  check(recovered, 'QA_RECOVERY_TIMEOUT')
  const final = await inventory()
  check(isDeepStrictEqual(final, baseline), 'QA_SEEDED_INVENTORY_CHANGED')
  metrics.recovery = { containerHealthy: true, healthHttp: 200, healthStatus: 'UP',
    totalElements: 500, qaRecords: 0, seededRecordsUnchanged: true, namedVolumeUnchanged: true,
    elapsedMs: Math.round(performance.now() - started) }
  console.log(JSON.stringify({ stage: 'recovery', ...metrics.recovery }))
}

try {
  check(process.argv.includes('--approved-stop'), 'QA_STOP_APPROVAL_REQUIRED')
  check(Boolean(process.env.DEV_ADMIN_PASSWORD), 'QA_MISSING_DEV_ADMIN_PASSWORD')
  const ids = (await docker(['ps', '--all', '--filter', `label=com.docker.compose.project.working_dir=${root}`,
    '--filter', 'label=com.docker.compose.service=mongodb', '--format', '{{.ID}}'])).split('\n').filter(Boolean)
  check(ids.length === 1 && /^[a-f0-9]{12,64}$/.test(ids[0]), 'QA_CONTAINER_NOT_UNIQUE')
  container = ids[0]
  const initial = await state()
  check(initial.running && initial.health === 'healthy', 'QA_MONGO_NOT_HEALTHY')
  mounts = initial.volumes
  health(await request('/actuator/health', { anonymous: true }), 'UP', 200)
  const csrf = await request('/api/v1/auth/csrf')
  check(csrf.status === 200 && typeof csrf.body?.token === 'string'
    && csrf.body.token === cookies.get('XSRF-TOKEN'), 'QA_CSRF_PAIR_INVALID')
  const login = await request('/api/v1/auth/login', { method: 'POST', token: csrf.body.token,
    body: { username: process.env.DEV_ADMIN_USERNAME || 'admin', password: process.env.DEV_ADMIN_PASSWORD } })
  check(login.status === 200 && login.body?.roles?.includes('ADMIN') && cookies.get('ACCESS_TOKEN'),
    'QA_ADMIN_LOGIN_FAILED')
  metrics.logins++
  baseline = await inventory()
  console.log(JSON.stringify({ stage, containerHealthy: true, totalElements: 500, qaRecords: 0 }))

  stage = 'mongo-stop'
  stopAttempted = true // Even a CLI timeout must enter the recovery finally block.
  await docker(['stop', '--time', '10', container], 25_000)
  const stopped = await state()
  check(!stopped.running && isDeepStrictEqual(stopped.volumes, mounts), 'QA_CONTAINER_NOT_STOPPED')
  console.log(JSON.stringify({ stage, running: false, namedVolumeUnchanged: true }))

  stage = 'outage-probes'
  // Drain both requests before recovery, including when one fails/times out.
  const probes = await Promise.allSettled([
    request('/actuator/health', { timeout: 45_000, anonymous: true }),
    request('/api/v1/products?page=0&size=1', { timeout: 45_000 }),
  ])
  check(probes.every(result => result.status === 'fulfilled'), 'QA_OUTAGE_PROBE_TIMEOUT_OR_FAILURE')
  const [healthResult, api] = probes.map(result => result.value)
  metrics.outage = { healthHttp: healthResult.status, healthStatus: healthResult.body?.status,
    healthElapsedMs: healthResult.elapsedMs, apiHttp: api.status, apiElapsedMs: api.elapsedMs,
    healthSanitized: sanitized(healthResult.body), apiSanitized: sanitized(api.body),
    problemDetail: api.type.includes('application/problem+json') && api.body?.status === api.status }
  // Emit only aggregate codes/booleans, never error bodies or header values.
  console.log(JSON.stringify({ stage, ...metrics.outage }))
  health(healthResult, 'DOWN', 503)
  check([500, 503].includes(api.status) && metrics.outage.problemDetail
    && typeof api.body.title === 'string' && typeof api.body.detail === 'string', 'QA_OUTAGE_API_CONTRACT_FAILED')
  check(Object.keys(api.body).every(key => ['type', 'title', 'status', 'detail', 'instance'].includes(key))
    && metrics.outage.apiSanitized, 'QA_OUTAGE_API_LEAK')
  check(!((await state()).running), 'QA_MONGO_UNEXPECTEDLY_RUNNING')
} catch (error) {
  failure = { stage, code: safeError(error) }
  console.log(JSON.stringify({ failure }))
} finally {
  if (stopAttempted) {
    try { await restore() } catch (error) {
      recoveryFailure = safeError(error)
      console.log(JSON.stringify({ recoveryFailure, requiresAttention: true }))
    }
  }
  cookies.clear()
}

console.log(JSON.stringify({ item: 'G3', status: failure || recoveryFailure ? 'FAILED' : 'PASSED', ...metrics }))
if (failure || recoveryFailure) process.exitCode = 1

import type { Page, Response } from '@playwright/test'
import type { ProductPage } from '../src/api/client'
import { test, expect, credentialsFor } from './support/fixtures'
import { QaFailure, UI_ORIGIN } from './support/qa-api'

function listResponse(page: Page, matches: (query: URLSearchParams) => boolean) {
  return page.waitForResponse(response => {
    const url = new URL(response.url())
    return url.origin === UI_ORIGIN && url.pathname === '/api/v1/products'
      && response.request().method() === 'GET' && matches(url.searchParams)
  })
}

async function productPage(response: Response): Promise<ProductPage> {
  expect(response.status()).toBe(200)
  return await response.json() as ProductPage
}

async function assertRendered(page: Page, result: ProductPage) {
  const rows = page.getByRole('table', { name: 'Product catalogue', exact: true }).getByRole('row')
  await expect(rows).toHaveCount(result.content.length + 1)
  for (const [index, product] of result.content.entries()) {
    const cells = rows.nth(index + 1).getByRole('cell')
    await expect(cells.nth(0)).toContainText(product.name)
    await expect(cells.nth(1)).toHaveText(product.category)
    await expect(cells.nth(2)).toHaveText(new Intl.NumberFormat(undefined, {
      style: 'currency', currency: 'USD', maximumFractionDigits: 2,
    }).format(product.price))
  }
}

test('E4.product-list-states-and-controls', async ({ page, context }) => {
  await context.route('**/*', route => new URL(route.request().url()).origin === UI_ORIGIN
    ? route.fallback() : route.abort('blockedbyclient'))
  await context.routeWebSocket('**/*', socket => {
    if (new URL(socket.url()).origin === 'ws://localhost:5173') socket.connectToServer()
    else socket.close()
