const filePath = (v) => text(v) && !v.includes('\\') && !v.includes('\0')
  && !v.startsWith('/') && !/^[A-Za-z]:/u.test(v)
  && v.split('/').every((part) => part !== '' && part !== '.' && part !== '..')
