import type { FullResult, Reporter, Suite, TestCase, TestError, TestResult } from '@playwright/test/reporter'
import { safeReason } from './qa-api'

/** Never serialize raw errors, titles, call logs, stdout, bodies or headers. */
export function resultRecord(title: string, status: TestResult['status'], durationMs: number,
  errors: readonly { message?: string }[]) {
  const id = title.match(/^E[1-9](?:\.[a-z0-9-]{1,40})?(?=\s|$)/i)?.[0] ?? 'SETUP'
  return {
    id, status, durationMs,
    ...(status === 'failed' || status === 'timedOut' || status === 'interrupted'
      ? { reason: safeReason(errors) } : {}),
  }
}

export default class SafeReporter implements Reporter {
  printsToStdio() { return true }
  onBegin(_config: unknown, suite: Suite) {
    process.stdout.write(`${JSON.stringify({ phase: 'start', tests: suite.allTests().length })}\n`)
  }
  onTestEnd(test: TestCase, result: TestResult) {
    process.stdout.write(`${JSON.stringify(resultRecord(test.title, result.status, result.duration, result.errors))}\n`)
  }
  onError(error: TestError) {
    const message = error.message ?? ''
    const reason = /No tests found/i.test(message) ? 'QA_NO_TESTS_DISCOVERED'
      : /fixture|destructuring/i.test(message) ? 'QA_FIXTURE_CONFIGURATION'
        : /Cannot find|Cannot load|module/i.test(message) ? 'QA_MODULE_RESOLUTION'
          : /browser|executable/i.test(message) ? 'QA_BROWSER_UNAVAILABLE'
            : 'QA_RUNNER_ERROR'
    process.stdout.write(`${JSON.stringify({ reason })}\n`)
  }
  onStdOut() { /* Deliberately discard worker output. */ }
  onStdErr() { /* Deliberately discard worker output. */ }
  onEnd(result: FullResult) {
    process.stdout.write(`${JSON.stringify({ phase: 'end', status: result.status })}\n`)
  }
}

import { constants, lstatSync, openSync, fstatSync, readFileSync, closeSync, opendirSync, realpathSync } from 'node:fs'
import { resolve, join } from 'node:path'
import { NONCE_MARKER } from './policy.mjs'

const TYPES = new Map([['js', 'text/javascript; charset=utf-8'], ['css', 'text/css; charset=utf-8'],
  ['svg', 'image/svg+xml'], ['png', 'image/png'], ['jpg', 'image/jpeg'], ['jpeg', 'image/jpeg'],
  ['webp', 'image/webp'], ['avif', 'image/avif'], ['ico', 'image/x-icon'], ['woff', 'font/woff'], ['woff2', 'font/woff2']])

// Startup-only indexing: request paths never become filesystem paths.
export function loadBuild(directory) {
  const root = resolve(directory)
  if (realpathSync(root) !== root || !lstatSync(root).isDirectory()) throw new Error('Invalid frontend build')
  let entries = 0
  let bytes = 0
  function read(path, limit) {
    const initial = lstatSync(path)
    if (initial.isSymbolicLink() || !initial.isFile()) throw new Error('Invalid frontend build')
    const fd = openSync(path, constants.O_RDONLY | constants.O_NOFOLLOW)
    try {
      const stat = fstatSync(fd)
      if (!stat.isFile() || stat.size > limit) throw new Error('Invalid frontend build')
      const body = readFileSync(fd)
      bytes += body.length
      if (body.length > limit || bytes > 64 * 1024 * 1024) throw new Error('Invalid frontend build')
      return body
    } finally { closeSync(fd) }
  }
  const template = read(join(root, 'index.html'), 256 * 1024).toString('utf8')
  if (template.split(NONCE_MARKER).length !== 2 || !template.includes('name="app-style-nonce"')) {
    throw new Error('Invalid frontend HTML build')
  }
  const assets = new Map()
  function walk(directory, prefix, depth) {
    if (depth > 8 || lstatSync(directory).isSymbolicLink()) throw new Error('Invalid frontend build')
    const handle = opendirSync(directory, { bufferSize: 1 })
    try {
      let entry
      while ((entry = handle.readSync()) !== null) {
        if (++entries > 1024 || entry.isSymbolicLink()) throw new Error('Invalid frontend build')
        if (!/^[A-Za-z0-9_-][A-Za-z0-9_.-]*$/.test(entry.name) || entry.name.endsWith('.map')) {
          throw new Error('Invalid frontend asset')
        }
        const file = join(directory, entry.name)
        const url = `${prefix}/${entry.name}`
        if (entry.isDirectory()) { walk(file, url, depth + 1); continue }
        const type = TYPES.get(entry.name.split('.').at(-1))
        if (!type) throw new Error('Invalid frontend asset')
        assets.set(url, { body: read(file, 8 * 1024 * 1024), type })
      }
    } finally {
      handle.closeSync()
    }
  }
  walk(join(root, 'assets'), '/assets', 0)
  return { template, assets }
}

import { afterEach, describe, expect, it } from 'vitest'
import { mkdtempSync, mkdirSync, writeFileSync, symlinkSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { loadBuild } from './assets.mjs'
import { NONCE_MARKER } from './policy.mjs'

const owned = []
afterEach(() => { for (const dir of owned.splice(0)) rmSync(dir, { recursive: true, force: true }) })
function build() {
  const directory = mkdtempSync(join(tmpdir(), 'qa-frontend-build-'))
  owned.push(directory)
  mkdirSync(join(directory, 'assets'))
  writeFileSync(join(directory, 'index.html'), `<meta name="app-style-nonce" content="${NONCE_MARKER}">`)
  writeFileSync(join(directory, 'assets', 'app-12345678.js'), 'export {}')
  return directory
}

describe('bounded startup asset indexing (owned temporary fixtures only)', () => {
  it('indexes a generated build, not arbitrary public/source files', () => {
    const directory = build()
    writeFileSync(join(directory, 'private.txt'), 'synthetic fixture')
    const result = loadBuild(directory)
    expect([...result.assets.keys()]).toEqual(['/assets/app-12345678.js'])
    expect(result.assets.get('/assets/app-12345678.js').body.toString()).toBe('export {}')
  })

  it.each(['.hidden', 'app.js.map', 'file.txt'])('rejects forbidden asset type/name: %s', name => {
    const directory = build()
    writeFileSync(join(directory, 'assets', name), 'synthetic fixture')
    expect(() => loadBuild(directory)).toThrow('Invalid frontend asset')
  })

  it('rejects a file symlink instead of following it', () => {
    const directory = build()
    symlinkSync(join(directory, 'index.html'), join(directory, 'assets', 'link.js'))
    expect(() => loadBuild(directory)).toThrow('Invalid frontend build')
  })

  it('rejects a symlink directory before reading its contents', () => {
    const directory = build()
    symlinkSync(join(directory, 'assets'), join(directory, 'assets', 'loop'))
    expect(() => loadBuild(directory)).toThrow('Invalid frontend build')
  })

  it('rejects an invalid/missing production marker', () => {
    const directory = build()
    writeFileSync(join(directory, 'index.html'), '<html></html>')
    expect(() => loadBuild(directory)).toThrow('Invalid frontend HTML build')
  })

  it('rejects oversized HTML', () => {
    const directory = build()
    writeFileSync(join(directory, 'index.html'), Buffer.alloc(256 * 1024 + 1))
    expect(() => loadBuild(directory)).toThrow('Invalid frontend build')
  })

  it('rejects oversized individual assets', () => {
    const directory = build()
    writeFileSync(join(directory, 'assets', 'large.js'), Buffer.alloc(8 * 1024 * 1024 + 1))
    expect(() => loadBuild(directory)).toThrow('Invalid frontend build')
  })

  it('bounds directory nesting', () => {
    const directory = build()
    let parent = join(directory, 'assets')
    for (let i = 0; i < 9; i++) { parent = join(parent, 'nested'); mkdirSync(parent) }
    expect(() => loadBuild(directory)).toThrow('Invalid frontend build')
  })

  it('bounds all visited entries, including empty directories', () => {
    const directory = build()
    for (let i = 0; i < 1024; i++) mkdirSync(join(directory, 'assets', `empty-${i}`))
    expect(() => loadBuild(directory)).toThrow('Invalid frontend build')
  })
})

import { describe, expect, it } from 'vitest'
import { htmlResponse, NONCE_MARKER, parseApiTarget, parseRequestPath, proxyHeaders } from './policy.mjs'

const template = `<html><meta name="app-style-nonce" content="${NONCE_MARKER}"></html>`

describe('standalone server policy (no sockets)', () => {
  it.each(['http://localhost:8080', 'https://api.example.test'])('accepts a configured origin: %s', target => {
    expect(parseApiTarget(target)).toBe(new URL(target).origin)
  })

  it.each([undefined, '', 'file:///tmp/build', 'ftp://api.example.test', 'http://name@localhost:8080',
    'http://localhost:8080/api', 'http://localhost:8080/?x=1', 'http://localhost:8080/#fragment'])('rejects invalid target %# without echoing it', target => {
    let message = ''
    try { parseApiTarget(target) } catch (error) { message = error.message }
    expect(message).toBe('FRONTEND_API_PROXY_TARGET must be an HTTP(S) origin without credentials or a path')
  })

  it.each(['/', '/login', '/assets/index-abc.js', '/api/v1/products?q=a%20b'])('accepts an origin-form path: %s', path => {
    expect(parseRequestPath(path)).toBe(path.split('?')[0])
  })

  it.each(['http://evil.example/api', '//evil.example/api', '/a/../index.html', '/a/./x', '/%2e%2e/x',
    '/%252e%252e/x', '/%2fapi', '/%5cfile', '/%00', '/bad%zz', '/a\\b', '/a#x', '/x\r\n', '/a b', '/x'.repeat(5000)])('rejects ambiguous paths %#', path => {
    expect(parseRequestPath(path)).toBeNull()
  })

  it('creates independent nonces and matching strict policy/body, without caching HTML', () => {
    const responses = Array.from({ length: 50 }, () => htmlResponse(template))
    const nonces = responses.map(r => r.body.toString().match(/content="([A-Za-z0-9+/]{32})"/)?.[1])
    expect(nonces.every(Boolean)).toBe(true)
    expect(new Set(nonces).size).toBe(50)
    expect(responses.every((r, i) => r.csp.includes(`'nonce-${nonces[i]}'`))).toBe(true)
    expect(responses.every(r => !r.body.toString().includes(NONCE_MARKER))).toBe(true)
    for (const response of responses) {
      expect(response.csp.includes('unsafe-inline')).toBe(false)
      expect(response.csp.includes('unsafe-eval')).toBe(false)
      expect(response.csp.includes('ws:')).toBe(false)
      expect(response.csp.includes("style-src-attr 'none'")).toBe(true)
      expect(response.csp.includes("script-src-attr 'none'")).toBe(true)
      expect(response.csp.includes("frame-ancestors 'none'")).toBe(true)
    }
  })

  it.each(['<html></html>', template + NONCE_MARKER, NONCE_MARKER])('rejects malformed/unsubstitutable builds %#', html => {
    expect(() => htmlResponse(html)).toThrow('Invalid frontend HTML build')
  })

  it('strips connection-nominated/hop headers and spoofed forwarding metadata, not auth/CSRF headers', () => {
    const cookie = ['qa', crypto.randomUUID()].join('=')
    const csrf = crypto.randomUUID()
    const result = proxyHeaders({ connection: 'keep-alive, x-hop', 'x-hop': 'remove', host: 'evil.example',
      forwarded: 'remove', 'x-forwarded-for': 'remove', 'x-forwarded-proto': 'remove',
      cookie, 'x-xsrf-token': csrf, origin: 'http://localhost:5173' }, true)
    expect(Object.keys(result).sort()).toEqual(['cookie', 'origin', 'x-xsrf-token'])
    expect(result.cookie === cookie && result['x-xsrf-token'] === csrf).toBe(true)
  })

  it('preserves separate Set-Cookie entries unchanged and removes server/hop headers', () => {
    const cookies = [crypto.randomUUID(), crypto.randomUUID()]
    const headers = proxyHeaders({ 'set-cookie': cookies, connection: 'x-hop', 'x-hop': 'remove',
      server: 'remove', 'x-powered-by': 'remove', 'content-type': 'application/json' })
    expect(headers['set-cookie'] === cookies).toBe(true)
    expect(Object.keys(headers).sort()).toEqual(['content-type', 'set-cookie'])
  })
})

/** The existing backend-compatible price grammar, unchanged: positive, 12 whole digits, 2 decimals. */
export function isValidProductPrice(value: string): boolean {
  return /^\d{1,12}(\.\d{1,2})?$/.test(value) && Number(value) > 0
}
